#include <stdlib.h>
#include <string.h>
#include "dump_info.h"
#include "tunnel.h"
#include "ssr_executive.h"
#include "ssr_client_api.h"
#include "common.h"
#include "udprelay.h"

#ifndef INET6_ADDRSTRLEN
# define INET6_ADDRSTRLEN 63
#endif

struct client_ssrot_udp_listener_ctx;

struct listener_t {
    uv_tcp_t *tcp_server;
    void *udp_server;
};

enum running_state {
    running_state_living = 0,
    running_state_quit = 1,
    running_state_dead = 2,
};

struct ssr_client_state {
    struct server_env_t *env;

    uv_signal_t *sigint_watcher;
    uv_signal_t *sigterm_watcher;

    uv_timer_t* exit_flag_timer;

    enum running_state running_state_flag;
    bool force_quit;
    int force_quit_delay_ms;

    int listener_count;
    struct listener_t *listeners;

    void(*feedback_state)(struct ssr_client_state *state, void *p);
    void *ptr;

    int error_code;
};

extern void udp_on_recv_data(struct client_ssrot_udp_listener_ctx *udp_ctx, const union sockaddr_universal *src_addr, const struct buffer_t *data, void*p);

static void getaddrinfo_done_cb(uv_getaddrinfo_t *req, int status, struct addrinfo *addrs);
static void listen_incoming_connection_cb(uv_stream_t *server, int status);
static void signal_quit(uv_signal_t* handle, int signum);
static void timer_quit_watcher_cb(uv_timer_t* handle);

int ssr_run_loop_begin(struct server_config *cf, void(*feedback_state)(struct ssr_client_state *state, void *p), void *p) {
    uv_loop_t * loop = NULL;
    struct addrinfo hints;
    struct ssr_client_state *state;
    int err;
    uv_getaddrinfo_t *req;
    char buff[256] = { 0 };

    config_ssrot_revision(cf);

    loop = (uv_loop_t *) calloc(1, sizeof(uv_loop_t));
    uv_loop_init(loop);

    state = (struct ssr_client_state *) calloc(1, sizeof(*state));
    state->running_state_flag = running_state_living;
    state->force_quit_delay_ms = 3000;
    state->listeners = NULL;
    state->env = ssr_cipher_env_create(cf, state);
    state->feedback_state = feedback_state;
    state->ptr = p;

    loop->data = state->env;

    /* Resolve the address of the interface that we should bind to.
    * The getaddrinfo callback starts the server and everything else.
    */
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    req = (uv_getaddrinfo_t *)calloc(1, sizeof(*req));

    err = uv_getaddrinfo(loop, req, getaddrinfo_done_cb, cf->listen_host, NULL, &hints);
    if (err != 0) {
        pr_err("getaddrinfo: %s", uv_strerror_r(err, buff, sizeof(buff)));
        if (state->feedback_state) {
            state->error_code = err;
            state->feedback_state(state, state->ptr);
        }
        return err;
    }

    // Setup signal handler
    state->sigint_watcher = (uv_signal_t *) calloc(1, sizeof(uv_signal_t));
    uv_signal_init(loop, state->sigint_watcher);
    uv_signal_start(state->sigint_watcher, signal_quit, SIGINT);

    state->sigterm_watcher = (uv_signal_t *) calloc(1, sizeof(uv_signal_t));
    uv_signal_init(loop, state->sigterm_watcher);
    uv_signal_start(state->sigterm_watcher, signal_quit, SIGTERM);

    state->exit_flag_timer = (uv_timer_t*) calloc(1, sizeof(uv_timer_t));
    uv_timer_init(loop, state->exit_flag_timer);
    uv_timer_start(state->exit_flag_timer, timer_quit_watcher_cb, 0, 500);

    /* Start the event loop.  Control continues in getaddrinfo_done_cb(). */
    err = uv_run(loop, UV_RUN_DEFAULT);
    if (err != 0) {
        char buff[256] = { 0 };
        pr_err("uv_run: %s", uv_strerror_r(err, buff, sizeof(buff)));
    }

    if (uv_loop_close(loop) != 0) {
        if (state->force_quit == false) {
#if ANDROID
            ASSERT(false);
#endif
        }
    }

    /* uv_library_shutdown(); */

    ssr_cipher_env_release(state->env);

    if (state->listeners) {
        free(state->listeners);
    }

    free(state->sigint_watcher);
    free(state->sigterm_watcher);
    free(state->exit_flag_timer);

    free(state);

    free(loop);

    return err;
}

static void tcp_close_done_cb(uv_handle_t* handle) {
    free((void *)((uv_tcp_t *)handle));
}

void state_set_force_quit(struct ssr_client_state *state, bool force_quit, int delay_ms) {
    state->force_quit = force_quit;
    state->force_quit_delay_ms = delay_ms;
}

void force_quit_timer_close_cb(uv_handle_t* handle) {
    // For some reason, uv_close may NOT always be work fine. 
    // sometimes uv_close_cb perhaps never called. 
    // so we have to call uv_stop to force exit the loop.
    // it can caused memory leaking. but who cares it?
    uv_stop(handle->loop);
    free(handle);
}

void force_quit_timer_cb(uv_timer_t* handle) {
    uv_close((uv_handle_t*)handle, force_quit_timer_close_cb);
}

void ssr_run_loop_shutdown(struct ssr_client_state *state) {
    if (state==NULL) {
        return;
    }

    if (state->running_state_flag != running_state_living) {
        return;
    }
    state->running_state_flag = running_state_quit;
}

void _ssr_run_loop_shutdown(struct ssr_client_state* state) {
    ASSERT(state->running_state_flag != running_state_living);
    state->running_state_flag = running_state_dead;

    uv_signal_stop(state->sigint_watcher);
    uv_close((uv_handle_t*)state->sigint_watcher, NULL);
    uv_signal_stop(state->sigterm_watcher);
    uv_close((uv_handle_t*)state->sigterm_watcher, NULL);

    uv_timer_stop(state->exit_flag_timer);
    uv_close((uv_handle_t*)state->exit_flag_timer, NULL);

    if (state->listeners && state->listener_count) {
        bool is_ssrot = state->env->config->over_tls_enable;
        size_t n = 0;
        for (n = 0; n < (size_t) state->listener_count; ++n) {
            struct listener_t *listener = state->listeners + n;
            void *udp_server = listener->udp_server;

            uv_tcp_t *tcp_server = listener->tcp_server;
            if (tcp_server) {
                uv_close((uv_handle_t *)tcp_server, tcp_close_done_cb);
            }

            if (is_ssrot) {
                client_ssrot_udprelay_shutdown((struct client_ssrot_udp_listener_ctx*)udp_server);
            } else {
                client_udprelay_shutdown((struct client_udp_listener_ctx *)udp_server);
            }
        }
    }

    client_env_shutdown(state->env);

    pr_info(" ");
    pr_info("terminated.\n");

    if (state->force_quit) {
        uv_timer_t *t = (uv_timer_t*) calloc(1, sizeof(*t));
        uv_timer_init(state->sigint_watcher->loop, t);
        uv_timer_start(t, force_quit_timer_cb, state->force_quit_delay_ms, 0); // wait 3 seconds.
    }
}

int ssr_get_listen_socket_fd(struct ssr_client_state *state) {
    if (state==NULL || state->listener_count==0 || state->listeners==NULL) {
        return 0;
    }
    ASSERT(state->listener_count == 1);
    return (int) uv_stream_fd(state->listeners[0].tcp_server);
}

int ssr_get_client_error_code(struct ssr_client_state* state) {
    return state ? state->error_code : -1;
}

/* Bind a server to each address that getaddrinfo() reported. */
static void getaddrinfo_done_cb(uv_getaddrinfo_t *req, int status, struct addrinfo *addrs) {
    char addrbuf[INET6_ADDRSTRLEN + 1];
    unsigned int ipv4_naddrs;
    unsigned int ipv6_naddrs;
    struct ssr_client_state *state;
    struct server_env_t *env;
    const struct server_config *cf;
    struct addrinfo *ai;
    const void *addrv = NULL;
    const char *what;
    uv_loop_t *loop;
    unsigned int n;
    int err;
    union sockaddr_universal s = { {0} };

    loop = req->loop;

    env = (struct server_env_t *) loop->data;
    state = (struct ssr_client_state *) env->data;
    ASSERT(state);
    cf = env->config;

    free(req);

    if (status < 0) {
        char buff[256] = { 0 };
        pr_err("getaddrinfo(\"%s\"): %s", cf->listen_host, uv_strerror_r(status, buff, sizeof(buff)));
        uv_freeaddrinfo(addrs);
        if (state->feedback_state) {
            state->error_code = status;
            state->feedback_state(state, state->ptr);
        }
        return;
    }

    ipv4_naddrs = 0;
    ipv6_naddrs = 0;
    for (ai = addrs; ai != NULL; ai = ai->ai_next) {
        if (ai->ai_family == AF_INET) {
            ipv4_naddrs += 1;
        } else if (ai->ai_family == AF_INET6) {
            ipv6_naddrs += 1;
        }
    }

    if (ipv4_naddrs == 0 && ipv6_naddrs == 0) {
        pr_err("%s has no IPv4/6 addresses", cf->listen_host);
        uv_freeaddrinfo(addrs);
        return;
    }

    state->listener_count = (ipv4_naddrs + ipv6_naddrs);
    state->listeners = (struct listener_t *) calloc(state->listener_count, sizeof(state->listeners[0]));

    n = 0;
    for (ai = addrs; ai != NULL; ai = ai->ai_next) {
        struct listener_t *listener;
        uv_tcp_t *tcp_server;
        uint16_t port;

        if (ai->ai_family != AF_INET && ai->ai_family != AF_INET6) {
            continue;
        }

        if (ai->ai_family == AF_INET) {
            s.addr4 = *(const struct sockaddr_in *) ai->ai_addr;
            s.addr4.sin_port = htons(cf->listen_port);
            addrv = &s.addr4.sin_addr;
        } else if (ai->ai_family == AF_INET6) {
            s.addr6 = *(const struct sockaddr_in6 *) ai->ai_addr;
            s.addr6.sin6_port = htons(cf->listen_port);
            addrv = &s.addr6.sin6_addr;
        } else {
            UNREACHABLE();
        }

        if (uv_inet_ntop(s.addr.sa_family, addrv, addrbuf, sizeof(addrbuf)) != 0) {
            UNREACHABLE();
        }

        listener = state->listeners + n;

        listener->tcp_server = (uv_tcp_t *)calloc(1, sizeof(listener->tcp_server[0]));
        tcp_server = listener->tcp_server;
        VERIFY(0 == uv_tcp_init(loop, tcp_server));

        what = "uv_tcp_bind";
        err = uv_tcp_bind(tcp_server, &s.addr, 0);
        if (err == 0) {
            // https://unix.stackexchange.com/questions/180492/is-it-possible-to-connect-to-tcp-port-0
            what = "uv_listen";
            err = uv_listen((uv_stream_t *)tcp_server, 128, listen_incoming_connection_cb);
        }

        if (state->feedback_state) {
            state->error_code = err;
            state->feedback_state(state, state->ptr);
        }

        if (err != 0) {
            char buff[256] = { 0 };
            pr_err("%s(\"%s:%hu\"): %s", what, addrbuf, cf->listen_port, uv_strerror_r(err, buff, sizeof(buff)));
            ssr_run_loop_shutdown(state);
            break;
        }

        port = get_socket_port(tcp_server);

        if (s.addr6.sin6_family == AF_INET6) {
            pr_info("listening on     [%s]:%hu\n", addrbuf, port);
        } else {
            pr_info("listening on     %s:%hu\n", addrbuf, port);
        }

        if (cf->udp) {
            union sockaddr_universal remote_addr = { {0} };
            universal_address_from_string(cf->remote_host, cf->remote_port, true, &remote_addr);
            if (cf->over_tls_enable) {
                struct client_ssrot_udp_listener_ctx *udp_server = 
                    client_ssrot_udprelay_begin(loop, cf->listen_host, port, &remote_addr);
                udp_relay_set_udp_on_recv_data_callback(udp_server, &udp_on_recv_data, NULL);
                listener->udp_server = (void*)udp_server;
            } else {
                listener->udp_server = (void *)
                    client_udprelay_begin(loop, cf->listen_host, port, &remote_addr,
                    state->env->cipher, 0, (int)cf->udp_timeout, cf->protocol, cf->protocol_param);
            }
        }

        n += 1;
    }

    uv_freeaddrinfo(addrs);
}

static void listen_incoming_connection_cb(uv_stream_t *server, int status) {
    uv_loop_t *loop = server->loop;
    struct server_env_t *env = (struct server_env_t *)loop->data;

    VERIFY(status == 0);
    client_tunnel_initialize((uv_tcp_t *)server, env->config->idle_timeout);
}

static void signal_quit(uv_signal_t* handle, int signum) {
    switch (signum) {
    case SIGINT:
    case SIGTERM:
#if !defined(__MINGW32__) && !defined(_WIN32)
    case SIGUSR1:
#endif
    {
        struct server_env_t *env;
        struct ssr_client_state *state;
        ASSERT(handle);
        env = (struct server_env_t *)handle->loop->data;
        state = (struct ssr_client_state *)env->data;
        ASSERT(state);
        ssr_run_loop_shutdown(state);
    }
        break;
    default:
        ASSERT(0);
        break;
    }
}

static void timer_quit_watcher_cb(uv_timer_t* handle) {
    struct server_env_t* env;
    struct ssr_client_state* state;
    ASSERT(handle);
    env = (struct server_env_t*)handle->loop->data;
    state = (struct ssr_client_state*)env->data;
    ASSERT(state);
    if (state->running_state_flag == running_state_quit) {
        _ssr_run_loop_shutdown(state);
    }
}

tls_cli_c:
#include "tls_cli.h"
#include "ref_count_def.h"
#include <uv-mbed/uv-mbed.h>
#include <uv.h>

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct tls_cli_ctx {
    uv_mbed_t* mbed;

    REF_COUNT_MEMBER;

    tls_cli_tcp_socket_created_cb socket_created;
    void* socket_created_p;

    tls_cli_on_connection_established_cb on_connection_established;
    void* on_connection_established_p;

    tls_cli_on_write_done_cb on_write_done;
    void* on_write_done_p;

    tls_cli_on_data_received_cb on_data_received;
    void* on_data_received_p;

    tls_cli_on_shutting_down_cb on_shutting_down;
    void* on_shutting_down_p;
};

void _tls_cli_free_internal(struct tls_cli_ctx* tls_cli) {
    if (tls_cli) {
        uv_mbed_release(tls_cli->mbed);
        free(tls_cli);
    }
}

REF_COUNT_ADD_REF_IMPL(tls_cli_ctx)
REF_COUNT_RELEASE_IMPL(tls_cli_ctx, _tls_cli_free_internal)

uv_os_sock_t tls_client_get_tcp_fd(const struct tls_cli_ctx* cli) {
    if (cli) {
        return uv_mbed_get_stream_fd(cli->mbed);
    }
    return -1;
}

bool tls_cli_is_closing(struct tls_cli_ctx* ctx) {
    return ctx && uv_mbed_is_closing(ctx->mbed);
}

static void _mbed_connect_done_cb(uv_mbed_t* mbed, int status, void* p);
static void _uv_mbed_socket_created_cb(uv_mbed_t* mbed, void* p);
static void _mbed_close_done_cb(uv_mbed_t* mbed, void* p);

struct tls_cli_ctx* tls_client_allocate(uv_loop_t* loop, const char* domain) {
    struct tls_cli_ctx* ctx = (struct tls_cli_ctx*)calloc(1, sizeof(*ctx));
    ctx->mbed = uv_mbed_init(loop, domain, ctx, 0);

    // this call purpose is for Android protect socket only.
    uv_mbed_set_tcp_socket_created_callback(ctx->mbed, &_uv_mbed_socket_created_cb, ctx);

    tls_cli_ctx_add_ref(ctx); // for the holder.

    return ctx;
}

int tls_client_launch(struct tls_cli_ctx* ctx, const char* ip_addr, int port, uint64_t timeout_msec) {
    int status = -1;

    tls_cli_ctx_add_ref(ctx); // for connect.
    status = uv_mbed_connect(ctx->mbed, ip_addr, port, timeout_msec, _mbed_connect_done_cb, ctx);

    if (status < 0) {
        tls_cli_ctx_add_ref(ctx); // for uv_mbed_close call
        uv_mbed_close(ctx->mbed, _mbed_close_done_cb, ctx);
    }
    return status;
}

static void _uv_mbed_socket_created_cb(uv_mbed_t* mbed, void* p) {
    struct tls_cli_ctx* ctx = (struct tls_cli_ctx*)p;
    assert(ctx->mbed == mbed);
    if (ctx->socket_created) {
        ctx->socket_created(ctx, ctx->socket_created_p);
    }
    (void)mbed;
}

static void _mbed_alloc_cb(uv_mbed_t* mbed, size_t suggested_size, uv_buf_t* buf) {
    char* base = (char*)calloc(suggested_size, sizeof(char));
    *buf = uv_buf_init(base, (unsigned int)suggested_size);
    (void)mbed;
}

static void _mbed_data_received_cb(uv_mbed_t* mbed, ssize_t nread, uv_buf_t* buf, void* p) {
    struct tls_cli_ctx* ctx = (struct tls_cli_ctx*)p;
    assert(ctx);
    assert(ctx->mbed == mbed);
    (void)mbed;

    if (ctx->on_data_received) {
        ctx->on_data_received(ctx, (int)nread, (uint8_t*)buf->base, (size_t)(nread > 0 ? nread : 0), ctx->on_data_received_p);
    }

    free(buf->base);
}

static void _mbed_connect_done_cb(uv_mbed_t* mbed, int status, void* p) {
    struct tls_cli_ctx* ctx = (struct tls_cli_ctx*)p;

    if (status >= 0) {
        uv_mbed_set_read_callback(mbed, _mbed_alloc_cb, _mbed_data_received_cb, p);
    }

    if (ctx->on_connection_established) {
        ctx->on_connection_established(ctx, status, ctx->on_connection_established_p);
    }

    tls_cli_ctx_release(ctx);
}

static void _mbed_write_done_cb(uv_mbed_t* mbed, int status, void* p) {
    struct tls_cli_ctx* ctx = (struct tls_cli_ctx*)p;
    assert(ctx->mbed == mbed);
    (void)mbed;

    if (ctx->on_write_done) {
        ctx->on_write_done(ctx, status, ctx->on_write_done_p);
    }

    tls_cli_ctx_release(ctx);
}

void tls_client_send_data(struct tls_cli_ctx* ctx, const uint8_t* data, size_t size) {
    uv_buf_t o = uv_buf_init((char*)data, (unsigned int)size);
    assert(ctx);
    if (ctx) {
        tls_cli_ctx_add_ref(ctx);
        uv_mbed_write(ctx->mbed, &o, &_mbed_write_done_cb, ctx);
    }
}

static void _mbed_close_done_cb(uv_mbed_t* mbed, void* p) {
    struct tls_cli_ctx* ctx = (struct tls_cli_ctx*)p;
    assert(ctx->mbed == mbed);
    (void)mbed;
    if (ctx && ctx->on_shutting_down) {
        ctx->on_shutting_down(ctx, ctx->on_shutting_down_p);
    }
    tls_cli_ctx_release(ctx);
}

void tls_client_shutdown(struct tls_cli_ctx* ctx, tls_cli_on_shutting_down_cb cb, void* p) {
    assert(ctx);
    if (ctx) {
        ctx->on_shutting_down = cb;
        ctx->on_shutting_down_p = p;

        tls_cli_ctx_add_ref(ctx);
        uv_mbed_close(ctx->mbed, _mbed_close_done_cb, ctx);
    }
}

void tls_cli_set_tcp_socket_created_callback(struct tls_cli_ctx* cli, tls_cli_tcp_socket_created_cb cb, void* p) {
    if (cli) {
        cli->socket_created = cb;
        cli->socket_created_p = p;
    }
}

void tls_cli_set_on_connection_established_callback(struct tls_cli_ctx* tls_cli, tls_cli_on_connection_established_cb cb, void* p) {
    if (tls_cli) {
        tls_cli->on_connection_established = cb;
        tls_cli->on_connection_established_p = p;
    }
}

void tls_cli_set_on_write_done_callback(struct tls_cli_ctx* tls_cli, tls_cli_on_write_done_cb cb, void* p) {
    if (tls_cli) {
        tls_cli->on_write_done = cb;
        tls_cli->on_write_done_p = p;
    }
}

void tls_cli_set_on_data_received_callback(struct tls_cli_ctx* tls_cli, tls_cli_on_data_received_cb cb, void* p) {
    if (tls_cli) {
        tls_cli->on_data_received = cb;
        tls_cli->on_data_received_p = p;
    }
}

